task_global_submission_snapshot.source:
mut global_value := 0
func factory() {
 mut local_value := 0
 async func work(write) {
  if write { global_value = 9 local_value += 1 }
  return [global_value, local_value]
 }
 return work
}
let work := factory()
print(await work(true))
global_value = 42
print(await work(false))
print(global_value)

